// src/pages/Profile.js

import { FiSettings } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import { useRef } from "react";

const books = [
  { title: "노르웨이의 숲", review: "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다." },
  { title: "데미안", review: "자기 자신을 찾아가는 과정이 정말 인상 깊었다." },
  { title: "어린왕자", review: "어른이 된다는 건 무엇일까 다시 생각하게 만든 책이었다." },
  { title: "1984", review: "감시 사회의 무서움을 현실적으로 보여줘서 몰입감이 강했다." },
  { title: "해변의 카프카", review: "현실과 환상이 섞이는 분위기가 매력적이었다." },
  { title: "채식주의자", review: "인물의 심리 변화가 굉장히 강렬했다." },
  { title: "82년생 김지영", review: "평범한 일상 속 차별이 얼마나 깊은지 느꼈다." },
  { title: "파친코", review: "세대를 넘는 이야기가 깊은 여운을 남겼다." },
  { title: "아몬드", review: "감정을 느끼지 못하는 주인공이 오히려 많은 감정을 불러일으켰다." },
];

const heights = [180, 220, 160, 200, 175, 215, 165, 190, 205];
const colors = ["#7bc142", "#a8d84e", "#5aab35", "#c5e87a", "#68b83e", "#b2de5f", "#4e9e2f", "#d4f09a", "#89c94f"];

function Profile() {
  const navigate = useNavigate();
  const currentUser = JSON.parse(localStorage.getItem("currentUser"));
  const userName = currentUser?.name || "READLY";
  const shelfRef = useRef(null);
  let isDragging = useRef(false);
  let startX = useRef(0);
  let scrollLeft = useRef(0);

  const onMouseDown = (e) => {
    isDragging.current = true;
    startX.current = e.pageX - shelfRef.current.offsetLeft;
    scrollLeft.current = shelfRef.current.scrollLeft;
    shelfRef.current.style.cursor = "grabbing";
  };
  const onMouseMove = (e) => {
    if (!isDragging.current) return;
    e.preventDefault();
    const x = e.pageX - shelfRef.current.offsetLeft;
    const walk = (x - startX.current) * 1.2;
    shelfRef.current.scrollLeft = scrollLeft.current - walk;
  };
  const onMouseUp = () => {
    isDragging.current = false;
    shelfRef.current.style.cursor = "grab";
  };

  return (
    <div className="page" style={{ display: "flex", flexDirection: "column", minHeight: "100vh" }}>

      {/* 상단 */}
      <div className="profile-header">
        <div className="logo">READLY</div>
        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}
      <div className="profile-top">
        <div className="profile-image">
          <img
            src="/images/프로필사진.png"
            alt="프로필"
            style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "50%" }}
          />
        </div>
        <div className="profile-info">
          <div className="profile-name">{userName} ✏️</div>
          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">100</div>
              <div className="follow-text">팔로워</div>
            </div>
            <div className="follow-box">
              <div className="follow-num">100</div>
              <div className="follow-text">팔로잉</div>
            </div>
          </div>
        </div>
      </div>

      {/* 소개 */}
      <div className="profile-desc">
        에세이를 좋아하는 책린이 입니다!
        <br />
        instagram: xx_123
      </div>

      <div className="line"></div>

      {/* 책장 배경 영역 — portal 없이 일반 흐름 */}
      <div style={{
        flex: 1,
        background: `
          radial-gradient(ellipse at 80% 0%, rgba(255,220,120,0.18) 0%, transparent 60%),
          repeating-linear-gradient(90deg, transparent, transparent 39px, rgba(180,140,90,0.07) 39px, rgba(180,140,90,0.07) 40px),
          repeating-linear-gradient(180deg, transparent, transparent 39px, rgba(180,140,90,0.07) 39px, rgba(180,140,90,0.07) 40px),
          #f5ede0
        `,
        position: "relative",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        padding: "0 0 0 0",
        overflow: "hidden",
      }}>

        {/* 조명 */}
        <div style={{ position: "absolute", top: 24, right: 40, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div style={{ width: "2px", height: "28px", background: "#b89060" }} />
          <div style={{ width: "44px", height: "20px", background: "#c9a055", borderRadius: "0 0 22px 22px", position: "relative" }}>
            <div style={{
              position: "absolute", bottom: "-40px", left: "50%", transform: "translateX(-50%)",
              width: "120px", height: "60px",
              background: "radial-gradient(ellipse, rgba(255,210,80,0.22) 0%, transparent 70%)",
              pointerEvents: "none",
            }} />
          </div>
        </div>

        {/* 책 슬라이드 영역 */}
        <div
          ref={shelfRef}
          onMouseDown={onMouseDown}
          onMouseMove={onMouseMove}
          onMouseUp={onMouseUp}
          onMouseLeave={onMouseUp}
          style={{
            display: "flex",
            alignItems: "flex-end",
            gap: "0px",
            overflowX: "auto",
            overflowY: "visible",
            padding: "0 16px",
            cursor: "grab",
            scrollBehavior: "smooth",
            WebkitOverflowScrolling: "touch",
            scrollbarWidth: "none",
            msOverflowStyle: "none",
          }}
        >
          <style>{`
            div::-webkit-scrollbar { display: none; }
            .book-item {
              transition: transform 0.2s cubic-bezier(.34,1.56,.64,1), box-shadow 0.2s ease, filter 0.2s ease;
              flex-shrink: 0;
              cursor: pointer;
            }
            .book-item:hover {
              transform: translateY(-10px) scale(1.04) !important;
              filter: brightness(1.12) drop-shadow(0 8px 12px rgba(80,60,20,0.22));
              z-index: 10;
            }
            .book-item:active {
              transform: translateY(-4px) scale(0.98) !important;
            }
          `}</style>

          {books.map((book, index) => {
            const h = heights[index % heights.length];
            const bg = colors[index % colors.length];
            return (
              <div
                key={index}
                className="book-item"
                onClick={() => navigate("/review", { state: { title: book.title, review: book.review } })}
              >
                <div style={{
                  width: "48px", height: `${h}px`, background: bg,
                  borderRadius: "5px 5px 0 0",
                  display: "flex", justifyContent: "center", alignItems: "center",
                  color: "rgba(66,64,64,0.85)", fontSize: "11px", fontWeight: "700",
                  writingMode: "vertical-rl", textOrientation: "mixed",
                  overflow: "hidden", padding: "10px 0",
                  boxShadow: "inset -3px 0 6px rgba(0,0,0,0.08)",
                }}>
                  {book.title}
                </div>
              </div>
            );
          })}
        </div>

        {/* 나무 선반 */}
        <div style={{
          height: "14px",
          background: "linear-gradient(to bottom, #c8974a, #a87840)",
          borderRadius: "3px",
          boxShadow: "0 3px 8px rgba(120,80,30,0.18)",
        }} />

      </div>
    </div>
  );
}

export default Profile;
